-- V1 (P0.6): baseline schema of jars-api.
-- Primary keys are UUIDv7 generated by the application, so there is no database default for id.
-- One row per Cognito user, created lazily on the first authenticated request (flow F1).

CREATE TABLE users (
    id           UUID        PRIMARY KEY,
    cognito_sub  TEXT        NOT NULL,
    email        TEXT        NOT NULL,
    display_name TEXT,
    locale       TEXT        NOT NULL DEFAULT 'vi-VN',
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uk_users_cognito_sub UNIQUE (cognito_sub)
);

-- e-mail addresses are compared case-insensitively: "An@Mail.com" and "an@mail.com" are the same user
CREATE UNIQUE INDEX uk_users_email_lower ON users (lower(email));
